// Folders belong to the project; references always use stable item IDs.
let collectionProject='',collectionFolder={assets:'__all__',characters:'__all__'},selectedAssets=new Set(),mediaImportBusy=false,mediaImportStatus='',editingCollectionCharacter='';
function syncCollections(){KotobaLibrary.normalize(project);if(collectionProject!==project.id){collectionProject=project.id;collectionFolder={assets:'__all__',characters:'__all__'};selectedAssets.clear();if(!mediaImportBusy)mediaImportStatus=''}for(const kind of ['assets','characters'])if(!['__all__','__root__'].includes(collectionFolder[kind])&&!KotobaLibrary.folders(project,kind).some(f=>f.id===collectionFolder[kind]))collectionFolder[kind]='__all__';selectedAssets=new Set([...selectedAssets].filter(id=>project.assets.some(a=>a.id===id)))}
function libraryDestinationFolder(){syncCollections();return ['__all__','__root__'].includes(collectionFolder.assets)?'':collectionFolder.assets}
function folderOptions(kind,value=''){return '<option value="">未分类</option>'+KotobaLibrary.folders(project,kind).map(f=>`<option value="${esc(f.id)}" ${value===f.id?'selected':''}>${esc(KotobaLibrary.folderPath(project,kind,f.id))}</option>`).join('')}
function collectionItems(kind){const all=kind==='assets'?project.assets:project.characters,id=collectionFolder[kind];if(id==='__all__')return all;if(id==='__root__')return all.filter(a=>!a.folderId);const ids=KotobaLibrary.descendants(project,kind,id);return all.filter(a=>ids.has(a.folderId))}
function collectionTree(kind){const all=kind==='assets'?project.assets:project.characters,folders=KotobaLibrary.folders(project,kind),current=collectionFolder[kind];const row=(id,name,count,depth=0)=>`<button class="folder-row ${current===id?'active':''}" style="padding-left:${12+depth*14}px" data-action="collection-folder" data-kind="${kind}" data-id="${esc(id)}"><span>${esc(name)}</span><small>${count}</small></button>`;const children=(id,depth)=>folders.filter(f=>(f.parentId||'')===id).map(f=>row(f.id,'▸ '+f.name,all.filter(a=>KotobaLibrary.descendants(project,kind,f.id).has(a.folderId)).length,depth)+children(f.id,depth+1)).join('');return `<aside class="folder-sidebar"><strong>${kind==='assets'?'素材文件夹':'角色分类'}</strong>${row('__all__','全部',all.length)}${row('__root__','未分类',all.filter(a=>!a.folderId).length)}${children('',0)}<button class="btn small" data-action="collection-new-folder" data-kind="${kind}">＋ ${kind==='assets'?'新建文件夹':'新建分类'}</button>${!['__all__','__root__'].includes(current)?`<div class="folder-tools"><button class="btn small" data-action="collection-rename-folder" data-kind="${kind}">重命名</button><button class="btn small" data-action="collection-delete-folder" data-kind="${kind}">删除分类</button></div>`:''}</aside>`}
const collectionOtherView=otherView,collectionValidate=validateProject,collectionDialog=dialog;
otherView=function(){if(!['assets','people'].includes(view))return collectionOtherView();syncCollections();const kind=view==='assets'?'assets':'characters',visible=collectionItems(kind),folder=KotobaLibrary.folderPath(project,kind,collectionFolder[kind])||(['__all__'].includes(collectionFolder[kind])?'全部':'未分类');return `<div class="full-content collection-layout">${collectionTree(kind)}<section class="collection-main"><div class="collection-controls"><div class="collection-toolbar"><strong>${esc(folder)}</strong><button class="btn small" data-action="collection-undo">撤销</button>${kind==='assets'?`<button class="btn small" data-action="upload">单个导入</button><button class="btn primary small" data-action="media-batch" ${mediaImportBusy?'disabled':''}>批量导入</button><button class="btn small" data-action="media-directory" ${mediaImportBusy?'disabled':''}>导入文件夹</button>`:'<button class="btn primary small" data-action="new-character">＋ 添加角色</button>'}</div>${kind==='assets'?`<p class="field-note" id="mediaImportStatus">${esc(mediaImportStatus||'支持图片、音频；每个文件不超过 20 MB。导入文件夹会保留分类层级。')}</p><div class="collection-selection"><div class="toggle">${[['all','全部素材'],['image','图片'],['audio','音频']].map(([id,label])=>`<button data-action="filter" data-id="${id}" class="${assetFilter===id?'active':''}">${label}</button>`).join('')}</div><button class="btn small" data-action="collection-select-all">选中本页</button><button class="btn small" data-action="collection-select-none">取消选择</button><span>${selectedAssets.size} 项已选</span>${selectedAssets.size?`<select aria-label="移动选中素材" data-collection-bulk><option value="__choose__">移动到…</option>${folderOptions('assets')}</select><button class="btn small" data-action="collection-delete-selected">删除所选</button>`:''}</div>`:''}</div><div class="card-grid collection-cards">${kind==='assets'?visible.filter(a=>assetFilter==='all'||a.type===assetFilter).map(a=>`<div class="asset-card" data-id="${esc(a.id)}"><label class="asset-select"><input type="checkbox" data-asset-select="${esc(a.id)}" ${selectedAssets.has(a.id)?'checked':''}> 选择</label><div class="asset-thumb">${a.type==='image'?`<img loading="lazy" src="${esc(editorMediaSource(a))}" alt="${esc(a.name)}">`:ic('music')}</div><div class="card-body"><h3 title="${esc(a.name)}">${esc(a.name)}</h3><p>${a.type==='image'?'图片':'音频'} · ${esc(KotobaLibrary.folderPath(project,kind,a.folderId)||'未分类')}</p><select aria-label="${esc(a.name)}的分类" data-collection-move="${esc(a.id)}" data-kind="assets">${folderOptions(kind,a.folderId)}</select><div class="card-actions"><button class="btn small" data-action="use-asset" data-id="${esc(a.id)}">加入剧本</button><button class="btn small" data-action="delete-asset" data-id="${esc(a.id)}">删除</button></div></div></div>`).join(''):visible.map(c=>{const image=KotobaCore.portraitAsset(project,c);return `<div class="character-card" data-id="${esc(c.id)}">${image?`<img class="variant-preview" loading="lazy" src="${esc(editorMediaSource(image))}" alt="${esc(c.name)}">`:`<div class="character-face" style="color:${esc(c.color)}">${esc(c.name.slice(-1))}</div>`}<h3>${esc(c.name)}</h3><p>${esc(c.description||'还没有角色介绍')}</p><p class="field-note">${c.variants?.length||0} 个立绘差分</p><select aria-label="${esc(c.name)}的分类" data-collection-move="${esc(c.id)}" data-kind="characters">${folderOptions(kind,c.folderId)}</select><div class="card-actions"><button class="btn small" data-action="edit-character" data-id="${esc(c.id)}">编辑角色</button><button class="btn small" data-action="variants" data-id="${esc(c.id)}">管理差分</button><button class="btn small" data-action="collection-delete-character" data-id="${esc(c.id)}">删除角色</button></div></div>`}).join('')}</div>${!visible.length?'<p class="empty">这里还没有内容。</p>':''}</section></div>`};
assetOptions=function(id,type='image'){return '<option value="">未选择素材</option>'+project.assets.filter(a=>a.type===type).map(a=>`<option value="${esc(a.id)}" ${a.id===id?'selected':''}>${esc(a.name)}${a.folderId?' · '+esc(KotobaLibrary.folderPath(project,'assets',a.folderId)):''}</option>`).join('')};
charOptions=function(id){return '<option value="">选择角色</option>'+project.characters.map(c=>`<option value="${esc(c.id)}" ${c.id===id?'selected':''}>${esc(c.name)}${c.folderId?' · '+esc(KotobaLibrary.folderPath(project,'characters',c.folderId)):''}</option>`).join('')};
validateProject=function(p){collectionValidate(p);KotobaLibrary.validate(p);return p};
dialog=function(title,body,submit,fn){if(['添加角色','编辑角色'].includes(title)){syncCollections();const c=character(editingCollectionCharacter),folder=c?.folderId||(!['__all__','__root__'].includes(collectionFolder.characters)?collectionFolder.characters:'');body+=`<div class="field"><label>角色分类</label><select name="folderId">${folderOptions('characters',folder)}</select></div>`}collectionDialog(title,body,submit,fn)};
function collectionFolderDialog(kind,rename=false){syncCollections();const current=KotobaLibrary.folders(project,kind).find(f=>f.id===collectionFolder[kind]);dialog(rename?'重命名分类':'新建分类',`<div class="field"><label>名称</label><input name="name" required maxlength="80" value="${esc(rename?current?.name||'':'新分类')}"></div>${rename?'':`<div class="field"><label>放在</label><select name="parentId">${folderOptions(kind,current?.id||'').replace('未分类','顶层')}</select></div>`}`,'保存',f=>{try{const name=f.get('name').trim(),parentId=rename?current.parentId||'':f.get('parentId');if(!name)throw Error('请输入分类名称');if(KotobaLibrary.folders(project,kind).some(x=>x.id!==current?.id&&x.name===name&&(x.parentId||'')===parentId))throw Error('同一位置已有同名分类');change(()=>{if(rename)current.name=name;else collectionFolder[kind]=KotobaLibrary.createFolder(project,kind,name,parentId).id})}catch(e){notify(e.message)}})}
function deleteCollectionCharacter(id){const c=character(id);if(!c)return;const refs=KotobaLibrary.characterReferences(project,id);dialog('删除角色',`<p>删除「${esc(c.name)}」。其图片素材会保留。可撤销恢复。</p><p>被 ${refs.dialogue} 句对白、${refs.portrait} 个立绘控制引用。</p><div class="field"><label>原有剧情的处理方式</label><select name="replacement"><option value="">保留文字，转为旁白；移除其立绘控制</option>${project.characters.filter(x=>x.id!==id).map(x=>`<option value="${esc(x.id)}">交给角色：${esc(x.name)}</option>`).join('')}</select></div>`,'删除角色',f=>{change(()=>{stopContentPlayback();KotobaLibrary.removeCharacter(project,id,f.get('replacement'));if(!scene().blocks.some(b=>b.id===selected))selected=scene().blocks[0]?.id});notify('角色已删除，剧情文字已保留')})}
function deleteCollectionAssets(ids){const chosen=project.assets.filter(a=>ids.includes(a.id));if(!chosen.length)return;dialog('删除素材',`<p>从工程中删除 ${chosen.length} 项素材。引用它们的背景、CG、立绘和字幕框将解除图片绑定。原始文件不受影响，可撤销恢复。</p>`,'删除素材',()=>{change(()=>KotobaLibrary.removeAssets(project,ids));selectedAssets.clear();draw();notify('素材已从工程中删除')})}
function applyImportedMedia(result,destination=''){let duplicate=0,added=0;change(()=>{for(const incoming of result.items){const folderId=KotobaLibrary.ensurePath(project,'assets',incoming.relativeFolder||'',destination);if(project.assets.some(a=>a.name===incoming.name&&(a.folderId||'')===folderId&&((incoming.contentHash&&a.contentHash===incoming.contentHash)||a.data===incoming.data))){duplicate++;continue}const {relativeFolder,...item}=incoming;project.assets.push({...item,folderId});added++}});return {added,duplicate}}
async function importCollectionMedia(mode){if(mediaImportBusy)return;if(!window.mediaImport){notify('请在桌面软件中使用批量或文件夹导入');return}syncCollections();const projectId=project.id,destination=libraryDestinationFolder();mediaImportBusy=true;mediaImportStatus='正在选择素材…';draw();try{const budget=256*1024*1024-projectStorageEstimate();const result=await window.mediaImport.choose({mode,budget});if(result.canceled){mediaImportStatus='已取消导入';return}if(project.id!==projectId){notify('工程已切换，本次素材未写入');return}const target=destination&&project.assetFolders.some(f=>f.id===destination)?destination:'';const {added,duplicate}=applyImportedMedia(result,target);mediaImportStatus=`已导入 ${added} 项${duplicate?'，跳过 '+duplicate+' 项重复素材':''}${result.skipped.length?'，另有 '+result.skipped.length+' 项未导入':''}`;notify(mediaImportStatus);if(result.skipped.length)dialog('素材导入结果',`<p>${esc(mediaImportStatus)}</p><div class="import-results">${result.skipped.slice(0,150).map(s=>`<p>${esc(s.name)}：${esc(s.reason)}</p>`).join('')}${result.skipped.length>150?'<p>仅显示前 150 项。</p>':''}</div>`,'完成',()=>{})}catch(e){mediaImportStatus='导入失败：'+e.message;notify(mediaImportStatus)}finally{mediaImportBusy=false;draw()}}
window.mediaImport?.onProgress(value=>{mediaImportStatus=`正在读取 ${value.current} / ${value.total}：${value.name}`;const el=$('#mediaImportStatus');if(el)el.textContent=mediaImportStatus});
document.addEventListener('click',e=>{const button=e.target.closest('[data-action]'),action=button?.dataset.action;if(['new-character','edit-character'].includes(action)){editingCollectionCharacter=action==='edit-character'?button.dataset.id:'';return}const actions=['collection-folder','collection-new-folder','collection-rename-folder','collection-delete-folder','collection-delete-character','collection-select-all','collection-select-none','collection-delete-selected','collection-undo','media-batch','media-directory','delete-asset'];if(!actions.includes(action))return;e.preventDefault();e.stopImmediatePropagation();const kind=button.dataset.kind;syncCollections();if(action==='collection-folder'){collectionFolder[kind]=button.dataset.id;selectedAssets.clear();draw()}if(action==='collection-new-folder'||action==='collection-rename-folder')collectionFolderDialog(kind,action==='collection-rename-folder');if(action==='collection-delete-folder'){const id=collectionFolder[kind],f=KotobaLibrary.folders(project,kind).find(x=>x.id===id);if(f)dialog('删除分类',`<p>删除「${esc(f.name)}」分类，里面的内容和子分类移到上一级。不会删除素材或角色。</p>`,'删除分类',()=>change(()=>{KotobaLibrary.removeFolder(project,kind,id);collectionFolder[kind]='__all__'}))}if(action==='collection-delete-character')deleteCollectionCharacter(button.dataset.id);if(action==='delete-asset')deleteCollectionAssets([button.dataset.id]);if(action==='collection-delete-selected')deleteCollectionAssets([...selectedAssets]);if(action==='collection-select-none'){selectedAssets.clear();draw()}if(action==='collection-select-all'){for(const a of collectionItems('assets').filter(a=>assetFilter==='all'||a.type===assetFilter))selectedAssets.add(a.id);draw()}if(action==='collection-undo')undoContentChange();if(action==='media-batch'||action==='media-directory')importCollectionMedia(action==='media-batch'?'files':'directory')},true);
document.addEventListener('change',e=>{const el=e.target;if(el.hasAttribute('data-asset-select')){if(el.checked)selectedAssets.add(el.dataset.assetSelect);else selectedAssets.delete(el.dataset.assetSelect);draw()}if(el.hasAttribute('data-collection-move'))change(()=>KotobaLibrary.moveItems(project,el.dataset.kind,[el.dataset.collectionMove],el.value));if(el.hasAttribute('data-collection-bulk')&&el.value!=='__choose__'){change(()=>KotobaLibrary.moveItems(project,'assets',[...selectedAssets],el.value));selectedAssets.clear();draw()}});
draw();
